create table if not exists accounting_documents (id bigserial primary key,title varchar(180) not null,category varchar(60) not null,reference_month char(7),original_name varchar(255) not null,storage_name varchar(255) not null unique,mime_type varchar(120) not null,file_size bigint not null default 0,notes text,uploaded_by bigint,created_at timestamp default current_timestamp);
create index if not exists accounting_documents_reference_idx on accounting_documents(reference_month,category);
create table if not exists accounting_document_events (id bigserial primary key,document_id bigint not null references accounting_documents(id),admin_user_id bigint not null references admin_users(id),event_type varchar(30) not null,ip_address varchar(80),user_agent varchar(500),created_at timestamp default current_timestamp);
create index if not exists accounting_events_document_idx on accounting_document_events(document_id,created_at);
create table if not exists accounting_messages (id bigserial primary key,sender_user_id bigint not null references admin_users(id),subject varchar(180) not null,message text not null,status varchar(30) not null default 'open',due_date date,created_at timestamp default current_timestamp);
create table if not exists suppliers_3d (id bigserial primary key,name varchar(160) not null,document_number varchar(30),contact_name varchar(120),email varchar(160),phone varchar(40),lead_time_days integer not null default 0,notes text,active boolean not null default true,created_at timestamp default current_timestamp);
create table if not exists filaments_3d (id bigserial primary key,supplier_id bigint references suppliers_3d(id),name varchar(140) not null,material varchar(40) not null,brand varchar(80),color varchar(80),diameter_mm numeric(5,2) not null default 1.75,spool_net_weight_g numeric(10,2) not null,current_weight_g numeric(10,2) not null,purchase_price numeric(12,2) not null,batch_code varchar(80),purchase_date date,minimum_stock_g numeric(10,2) not null default 0,active boolean not null default true,created_at timestamp default current_timestamp);
create table if not exists products_3d (id bigserial primary key,sku varchar(80) not null unique,name varchar(180) not null,description text,category varchar(80),license_type varchar(80),license_source varchar(255),license_notes text,print_time_minutes integer not null default 0,energy_cost numeric(12,2) not null default 0,labor_cost numeric(12,2) not null default 0,packaging_cost numeric(12,2) not null default 0,other_cost numeric(12,2) not null default 0,waste_percent numeric(7,2) not null default 0,sale_price numeric(12,2) not null default 0,stock_quantity numeric(10,2) not null default 0,minimum_stock numeric(10,2) not null default 0,image_path varchar(255),active boolean not null default true,created_at timestamp default current_timestamp);
create table if not exists product_filaments_3d (id bigserial primary key,product_id bigint not null references products_3d(id) on delete cascade,filament_id bigint not null references filaments_3d(id),quantity_g numeric(10,2) not null,unique(product_id,filament_id));
create table if not exists sales_channels_3d (id bigserial primary key,name varchar(140) not null unique,channel_type varchar(40) not null,contact_name varchar(120),fee_percent numeric(7,2) not null default 0,fixed_fee numeric(12,2) not null default 0,commission_percent numeric(7,2) not null default 0,active boolean not null default true,created_at timestamp default current_timestamp);
create table if not exists production_orders_3d (id bigserial primary key,product_id bigint not null references products_3d(id),quantity numeric(10,2) not null default 1,status varchar(30) not null default 'planned',started_at timestamp,completed_at timestamp,unit_cost_snapshot numeric(12,2) not null default 0,total_cost numeric(12,2) not null default 0,notes text,created_at timestamp default current_timestamp);
create table if not exists sales_3d (id bigserial primary key,product_id bigint not null references products_3d(id),channel_id bigint references sales_channels_3d(id),quantity numeric(10,2) not null default 1,unit_price numeric(12,2) not null,gross_amount numeric(12,2) not null,fees_amount numeric(12,2) not null default 0,cost_amount numeric(12,2) not null default 0,net_profit numeric(12,2) not null default 0,sold_at date not null,external_order_id varchar(120),created_at timestamp default current_timestamp);
insert into sales_channels_3d(name,channel_type,fee_percent) values ('Venda direta','direct',0),('Mercado Livre','marketplace',16),('Shopee','marketplace',20),('Amazon','marketplace',15),('Parceiro / ponto de venda','partner',0) on conflict do nothing;
